// Números inventados para practicar. No son de AdMob ni de Senda.
const solicitudes = 1000;      // veces que la app pidió un anuncio
const respondidas = 800;       // pedidos que recibieron un anuncio
const mostradas = 600;         // anuncios que de verdad se vieron en pantalla
const ganado = 1.5;            // USD estimados por esas impresiones

const matchRate = (respondidas / solicitudes) * 100;
const showRate = (mostradas / respondidas) * 100;
const ecpm = (ganado / mostradas) * 1000;
console.log("match rate:", matchRate.toFixed(0) + " %");
console.log("show rate:", showRate.toFixed(0) + " %");
console.log("eCPM:", ecpm.toFixed(2), "USD por mil impresiones");

// De eCPM a ganancia por persona y por día (ARPDAU)
const personasPorDia = 200;
const impresionesPorPersona = 3;
const impresionesDia = personasPorDia * impresionesPorPersona;
const gananciaDia = (ecpm * impresionesDia) / 1000;
console.log("impresiones por día:", impresionesDia);
console.log("ganancia por día:", gananciaDia.toFixed(2), "USD");
console.log("ARPDAU:", (gananciaDia / personasPorDia).toFixed(4), "USD");

// Datos INVENTADOS para entender la mecánica. No son cifras de AdMob ni de ninguna red.
let s = 12345;
const azar = () => { s = (s * 1664525 + 1013904223) % 4294967296; return s / 4294967296; };
// Cada red paga, por impresión, un eCPM que varía (en USD por mil): valor medio y dispersión distintos.
const redes = [
  { n: "Red A", medio: 3.0, rango: 4.0, llena: 0.55 },
  { n: "Red B", medio: 2.5, rango: 2.0, llena: 0.80 },
  { n: "Red C", medio: 1.5, rango: 1.0, llena: 0.95 },
];
const oferta = (r) => (azar() < r.llena ? Math.max(0, r.medio + (azar() - 0.5) * r.rango) : null);
const N = 20000;
let cascada = 0, subasta = 0, sinAnuncio = 0;
// Cascada: el dueño ordena las redes por el eCPM que ESPERA (A, B, C) y se llama una por una.
const orden = [redes[0], redes[1], redes[2]];
for (let i = 0; i < N; i++) {
  const o = redes.map(oferta);
  // cascada: la primera que responde se queda con la impresión
  const k = orden.findIndex((r) => o[redes.indexOf(r)] !== null);
  if (k < 0) sinAnuncio++; else cascada += o[redes.indexOf(orden[k])];
  // subasta: todas pujan a la vez y gana la oferta más alta
  const vivas = o.filter((x) => x !== null);
  if (vivas.length) subasta += Math.max(...vivas);
}
const llenasC = N - sinAnuncio;
console.log("Solicitudes:", N);
console.log("Cascada: eCPM medio =", (cascada / llenasC).toFixed(2), "USD por mil");
console.log("Subasta: eCPM medio =", (subasta / llenasC).toFixed(2), "USD por mil");
